{"command":"python3 - << 'PY'
import numpy as np, base64, sys, json, os

def create_waveform(wave, length=64, amplitude=0.8):
    if wave=='square':
        t=np.arange(length)
        data=np.where(t<length/2, amplitude, -amplitude)
    elif wave=='saw':
        data=( (np.arange(length)/length)*2 -1)*amplitude
    elif wave=='sine':
        data=np.sin(2*np.pi*np.arange(length)/length)*amplitude
    elif wave=='triangle':
        data=(2* np.abs(2*(np.arange(length)/length - np.floor(0.5+np.arange(length)/length))) -1)*amplitude
    else:
        raise ValueError
    return (data*32767).astype(np.int16)

sq=create_waveform('square', length=32, amplitude=0.8)
print(sq[:10])
enc=base64.b64encode(sq.tobytes()).decode('ascii')
print(len(enc))
open('/workspace/sq.b64','w').write(enc)
PY"}

